UPDATE zhw_story
title = #{title}, cover = #{cover}, setting_content = #{settingContent}, status = #{status}, update_by = #{updateBy}, update_time = NOW()
WHERE story_id = #{storyId}

UPDATE zhw_story
SET heat_score = participant_count * 30 + branch_count * 30 + comment_count * 3 + like_count * 1
WHERE story_id = #{storyId}
